import express from 'express';
import { createClient } from 'redis';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const redis = createClient({ url: process.env.REDIS_URL });
redis.connect();

// Session store with Redis
const SESSION_TTL = 3600;

app.post('/api/login', async (req, res) => {
  const { username, password } = req.body;
  // Simplified auth check (real app uses bcrypt)
  const userRecord = await redis.hGetAll(`user:${username}`);
  if (!userRecord || userRecord.password !== crypto.createHash('sha256').update(password).digest('hex')) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }
  const sessionId = crypto.randomBytes(32).toString('hex');
  await redis.set(`session:${sessionId}`, JSON.stringify({ username, role: userRecord.role }), { EX: SESSION_TTL });
  res.json({ token: sessionId });
});

// Middleware to check session
async function authenticate(req, res, next) {
  const token = req.headers['x-session-token'];
  if (!token) return res.status(401).json({ error: 'No token' });
  const session = await redis.get(`session:${token}`);
  if (!session) return res.status(401).json({ error: 'Invalid session' });
  req.session = JSON.parse(session);
  next();
}

// Password reset - generates a token stored in Redis
app.post('/api/password-reset', async (req, res) => {
  const { email } = req.body;
  if (!email) return res.status(400).json({ error: 'Email required' });

  // Find user by email scan (simplified)
  const keys = await redis.keys('user:*');
  let targetUser = null;
  for (const key of keys) {
    const u = await redis.hGetAll(key);
    if (u.email === email) {
      targetUser = key.replace('user:', '');
      break;
    }
  }
  if (!targetUser) return res.status(200).json({ message: 'If account exists, reset email sent' });

  const resetToken = crypto.randomBytes(16).toString('hex');
  // Store reset token - NOTE: key is constructed from user-supplied input
  const resetKey = `reset:${targetUser}:${resetToken}`;
  await redis.set(resetKey, targetUser, { EX: 900 });

  // In production, send email. Here we log it.
  console.log(`Reset token for ${targetUser}: ${resetToken}`);
  res.json({ message: 'If account exists, reset email sent' });
});

// Apply reset token
app.post('/api/password-reset/confirm', async (req, res) => {
  const { token, new_password } = req.body;
  if (!token || !new_password) return res.status(400).json({ error: 'Missing fields' });

  // Scan for matching reset token
  const resetKeys = await redis.keys(`reset:*:${token}`);
  if (resetKeys.length === 0) return res.status(400).json({ error: 'Invalid or expired token' });

  const username = await redis.get(resetKeys[0]);
  if (!username) return res.status(400).json({ error: 'Invalid token' });

  const hashedPw = crypto.createHash('sha256').update(new_password).digest('hex');
  await redis.hSet(`user:${username}`, 'password', hashedPw);
  await redis.del(resetKeys[0]);

  res.json({ message: 'Password updated' });
});

// Admin endpoint - fetch user data
app.get('/api/admin/users', authenticate, async (req, res) => {
  if (req.session.role !== 'admin') return res.status(403).json({ error: 'Forbidden' });
  const keys = await redis.keys('user:*');
  const users = [];
  for (const key of keys) {
    const u = await redis.hGetAll(key);
    users.push({ username: key.replace('user:', ''), email: u.email, role: u.role });
  }
  res.json(users);
});

// User profile update
app.put('/api/profile', authenticate, async (req, res) => {
  const { email, display_name } = req.body;
  const updates = {};
  if (email) updates.email = email;
  if (display_name) updates.display_name = display_name;
  // Vulnerability: user can inject 'role' field via prototype or extra fields
  Object.keys(req.body).forEach(key => {
    if (key !== 'password') {
      updates[key] = req.body[key];
    }
  });
  await redis.hSet(`user:${req.session.username}`, updates);
  res.json({ message: 'Profile updated' });
});

app.listen(3000, () => console.log('Server on :3000'));
